insert into public.notification_types (code, name, description, priority, template_title, template_message, default_enabled, created_at, email_template_html)
values ('transfer_otp', 'Código OTP para Transferencia', 'Código de verificación de 6 dígitos enviado por email para confirmar transferencias', '10', '{"en": "Verification Code", "es": "Código de Verificación"}', '{"en": "Your verification code to confirm the transfer.", "es": "Tu código de verificación para confirmar la transferencia."}', true, '2026-02-06 09:36:54.74083+00', '{"es": "<div style=\"font-family: sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #eee; border-radius: 10px;\"><h2 style=\"color: #1a1a1a;\">🔐 Código de Verificación</h2><p>Hola {{first_name}},</p><p>Tu código de verificación para confirmar la transferencia es:</p><div style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 30px; border-radius: 12px; margin: 25px 0; text-align: center;\"><p style=\"font-size: 42px; font-weight: bold; letter-spacing: 12px; color: #ffffff; margin: 0; font-family: ''Courier New'', monospace;\">{{otp_code}}</p></div><div style=\"background: #f9f9f9; padding: 15px; border-radius: 8px; margin: 20px 0;\"><p style=\"margin: 8px 0;\"><strong>Monto:</strong> {{amount_formatted}}</p><p style=\"margin: 8px 0;\"><strong>Destinatario:</strong> {{recipient_name}}</p></div><div style=\"background: #fef2f2; border-left: 4px solid #dc2626; padding: 12px 16px; margin: 20px 0; border-radius: 4px;\"><p style=\"color: #dc2626; font-size: 14px; margin: 0;\">⚠️ <strong>Importante:</strong> Este código expira en 2 minutos. No lo compartas con nadie.</p></div><p style=\"color: #666; font-size: 12px; margin-top: 20px;\">Si no solicitaste este código, ignora este mensaje.</p><p style=\"color: #666; font-size: 12px;\">Este es un correo automático, por favor no lo respondas.</p></div>"}')
on conflict (code) do nothing;

insert into public.notification_types (code, name, description, priority, template_title, template_message, default_enabled, created_at, email_template_html)
values ('transaction_received', 'Transferencia Recibida', null, '1', '{"en": "Transfer Received", "es": "Transferencia Recibida"}', '{"en": "You received money. Tap for details.", "es": "Has recibido dinero. Toca para ver detalles."}', true, '2026-01-31 06:40:34.343959+00', '{"es": "<div style=\"font-family: sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #eee; border-radius: 10px;\"><h2 style=\"color: #1a1a1a;\">{{title}}</h2><p>Hola {{first_name}},</p><p>{{message}}</p><div style=\"background: #f9f9f9; padding: 15px; border-radius: 8px; margin: 20px 0;\"><p><strong>Monto:</strong> {{amount_formatted}}</p><p><strong>Referencia:</strong> {{reference_number}}</p><p><strong>Fecha:</strong> {{date}}</p></div><p style=\"color: #666; font-size: 12px;\">Este es un correo automático, por favor no lo respondas.</p></div>"}')
on conflict (code) do nothing;

