on conflict (code) do nothing;

insert into public.notification_types (code, name, description, priority, template_title, template_message, default_enabled, created_at, email_template_html)
values ('email_verification', 'Verificación de Email', 'Código OTP enviado durante el registro para verificar el email del usuario', '10', '{"en": "Verify your email - Magnate", "es": "Verifica tu correo - Magnate"}', '{"en": "Your verification code is: {{otp_code}}", "es": "Tu código de verificación es: {{otp_code}}"}', true, '2026-02-26 03:25:02.147089+00', '{"es": "<!DOCTYPE html><html lang=\"es\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"><title>Verificación de Email - Magnate</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,sans-serif;background:#0f0f1a;color:#ffffff;}.container{max-width:520px;margin:40px auto;background:linear-gradient(145deg,#1a1a2e,#16213e);border-radius:24px;overflow:hidden;border:1px solid rgba(255,255,255,0.08);}.header{background:linear-gradient(135deg,#6c47ff,#a855f7);padding:40px 32px;text-align:center;}.header h1{font-size:28px;font-weight:800;color:#fff;letter-spacing:-0.5px;}.header p{color:rgba(255,255,255,0.8);margin-top:6px;font-size:15px;}.body{padding:36px 32px;}.greeting{font-size:17px;color:rgba(255,255,255,0.85);margin-bottom:24px;}.otp-box{background:rgba(108,71,255,0.12);border:1.5px solid rgba(108,71,255,0.4);border-radius:16px;padding:28px;text-align:center;margin:24px 0;}.otp-label{font-size:13px;text-transform:uppercase;letter-spacing:2px;color:rgba(255,255,255,0.5);margin-bottom:14px;}.otp-code{font-size:52px;font-weight:900;letter-spacing:12px;color:#a855f7;font-variant-numeric:tabular-nums;}.otp-expiry{margin-top:14px;font-size:13px;color:rgba(255,255,255,0.45);}.instructions{font-size:14px;color:rgba(255,255,255,0.55);line-height:1.7;margin-top:20px;}.warning{background:rgba(255,100,100,0.08);border-left:3px solid rgba(255,100,100,0.5);border-radius:4px;padding:12px 16px;margin-top:24px;font-size:13px;color:rgba(255,200,200,0.8);}.footer{background:rgba(255,255,255,0.02);border-top:1px solid rgba(255,255,255,0.06);padding:24px 32px;text-align:center;font-size:12px;color:rgba(255,255,255,0.3);line-height:1.6;}</style></head><body><div class=\"container\"><div class=\"header\"><h1>🔐 Magnate</h1><p>Verificación de identidad</p></div><div class=\"body\"><p class=\"greeting\">Hola, {{first_name}} 👋</p><p style=\"font-size:15px;color:rgba(255,255,255,0.65);line-height:1.6;\">Para completar tu registro en <strong>Magnate</strong>, ingresa el siguiente código de verificación en la aplicación:</p><div class=\"otp-box\"><p class=\"otp-label\">Tu código</p><p class=\"otp-code\">{{otp_code}}</p><p class=\"otp-expiry\">⏱ Expira en 10 minutos</p></div><p class=\"instructions\">Ingresa este código exactamente como aparece en la pantalla de verificación de la app. No lo compartas con nadie.</p><div class=\"warning\">⚠️ Si no solicitaste este código, ignora este correo. Tu cuenta está segura.</div></div><div class=\"footer\"><p><strong>Magnate Financial Freedom</strong></p><p style=\"margin-top:6px;\">Este es un mensaje automático. Por favor no respondas a este correo.</p></div></div></body></html>"}')
on conflict (code) do nothing;

insert into public.notification_types (code, name, description, priority, template_title, template_message, default_enabled, created_at, email_template_html)
values ('pin_change_otp', 'Cambio de PIN - Código de Verificación', 'Código OTP enviado al usuario cuando solicita cambiar su PIN de acceso.', '1', '{"en": "Verification Code - PIN Change", "es": "Código de verificación - Cambio de PIN"}', '{"en": "Your verification code for PIN change is: {{otp}}. Valid for 10 minutes.", "es": "Tu código de verificación para cambio de PIN es: {{otp}}. Válido por 10 minutos."}', true, '2026-02-27 16:59:01.037622+00', '{"es": "<!DOCTYPE html><html lang=\"es\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"><title>Cambio de PIN - Magnate</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,sans-serif;background:#0f0f1a;color:#ffffff;}.container{max-width:520px;margin:40px auto;background:linear-gradient(145deg,#1a1a2e,#16213e);border-radius:24px;overflow:hidden;border:1px solid rgba(255,255,255,0.08);}.header{background:linear-gradient(135deg,#6c47ff,#a855f7);padding:40px 32px;text-align:center;}.header h1{font-size:28px;font-weight:800;color:#fff;letter-spacing:-0.5px;}.header p{color:rgba(255,255,255,0.8);margin-top:6px;font-size:15px;}.body{padding:36px 32px;}.greeting{font-size:17px;color:rgba(255,255,255,0.85);margin-bottom:24px;}.otp-box{background:rgba(108,71,255,0.12);border:1.5px solid rgba(108,71,255,0.4);border-radius:16px;padding:28px;text-align:center;margin:24px 0;}.otp-label{font-size:13px;text-transform:uppercase;letter-spacing:2px;color:rgba(255,255,255,0.5);margin-bottom:14px;}.otp-code{font-size:52px;font-weight:900;letter-spacing:12px;color:#a855f7;font-variant-numeric:tabular-nums;}.otp-expiry{margin-top:14px;font-size:13px;color:rgba(255,255,255,0.45);}.instructions{font-size:14px;color:rgba(255,255,255,0.55);line-height:1.7;margin-top:20px;}.warning{background:rgba(255,100,100,0.08);border-left:3px solid rgba(255,100,100,0.5);border-radius:4px;padding:12px 16px;margin-top:24px;font-size:13px;color:rgba(255,200,200,0.8);}.footer{background:rgba(255,255,255,0.02);border-top:1px solid rgba(255,255,255,0.06);padding:24px 32px;text-align:center;font-size:12px;color:rgba(255,255,255,0.3);line-height:1.6;}</style></head><body><div class=\"container\"><div class=\"header\"><h1>🔑 Magnate</h1><p>Cambio de PIN de acceso</p></div><div class=\"body\"><p class=\"greeting\">Hola, {{first_name}} 👋</p><p style=\"font-size:15px;color:rgba(255,255,255,0.65);line-height:1.6;\">Recibimos una solicitud para cambiar tu PIN de acceso en <strong>Magnate</strong>. Ingresa el siguiente código de verificación en la aplicación:</p><div class=\"otp-box\"><p class=\"otp-label\">Tu código</p><p class=\"otp-code\">{{otp_code}}</p><p class=\"otp-expiry\">⏱ Expira en 10 minutos</p></div><p class=\"instructions\">Ingresa este código exactamente como aparece en la pantalla de verificación de la app. No lo compartas con nadie.</p><div class=\"warning\">⚠️ Si no solicitaste este cambio, te recomendamos cambiar tu PIN inmediatamente y contactar soporte.</div></div><div class=\"footer\"><p><strong>Magnate Financial Freedom</strong></p><p style=\"margin-top:6px;\">Este es un mensaje automático. Por favor no respondas a este correo.</p></div></div></body></html>"}')
on conflict (code) do nothing;
